export const traditionsId = (number: StoryLessonNumber) => `conversational-skills-L6-C1-${number}-${traditionsEpisodes[number].skill}-en-v1`;

export function buildTraditionsLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, traditionsEpisodes[number], previous, reference, {
    id: traditionsId(number), chapterName: 'Keeping Traditions Alive', pronunciation: naturalPronunciationLessons[1][number],
    setting: 'Kanazawa: Haru’s fictional family textile workshop, a hosted tea visit, Omicho Market and a community festival. Kaga Yuzen is a real craft; the characters and event arrangements are fictional.',
    previousSummary: index === 0 ? 'Four longtime friends are reuniting in Kanazawa after nearly five years apart.' : traditionsEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(6)}\nReference: Threads of Tradition, Chapter 1. Use this new cast only: Aiko, Haru, Mei, Daniel and Mrs. Takeda. No romance or inherited Kyoto/Tokyo plot. Eight story episodes map to 1-4 and 6-9; 5/10 are dynamic checkpoints. Preserve four English expressions, English-only content, standard numbered guides and fixed English feedback. No new images. A supervised dyeing activity is not a complete production manual or professional finished work. Tea guidance is attributed to Ms. Nakamura’s tradition, not universal practice; do not invent fixed turning counts. Festival interest does not guarantee the workshop’s future. Classes, the next event and reunion have no fixed dates or fees; the documentary is still unfinished at the farewell.`,
  });
  lesson.storyData.storyTitle = 'Threads of Tradition';
  lesson.storyData.characters = [
    { id: 'aiko', name: 'Aiko', role: 'main', description: 'Museum educator based in Tokyo. She values history, thoughtful questions and opportunities to learn through experience.' },
    { id: 'haru', name: 'Haru', role: 'supporting', description: 'Kanazawa native whose family practises Kaga Yuzen. He cares about the workshop but is unsure how to interest new learners.' },
    { id: 'mei', name: 'Mei', role: 'supporting', description: 'Chef from Kyoto. She explores regional and family recipes with energy and humour.' },
    { id: 'daniel', name: 'Daniel', role: 'supporting', description: 'Canadian photographer living in Japan. He asks curious questions and wants to share cultural stories respectfully.' },
    { id: 'takeda', name: 'Mrs. Takeda', role: 'supporting', description: 'Haru’s grandmother and an experienced Kaga Yuzen artisan. She guides the friends while considering new ways to share her work.' },
    { id: 'nakamura', name: 'Ms. Nakamura', role: 'supporting', description: 'Tea practitioner who explains the etiquette taught in her own tradition and welcomes respectful questions.' },
  ];
  if (number === 6) {
    const guide = lesson.missionData.tutorSteps[1];
    guide.scripts[0].text = "I'll be a committee member. Please be Aiko. You may use the useful language. I'll start.";
    lesson.applyData.tutorSteps[0].scripts[0].text = "I'll be a committee member. Please be Aiko. Is it clear? I'll start.";
  }
  return { ...lesson, course: 'conversational-skills', level: 6, chapter: 1, lessonNumber: number,
    levelBadge: 'INTERMEDIATE', chapterLabel: 'Chapter 1: Keeping Traditions Alive', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 550-780', authoringLanguageRevision: 'toeic-v1' };
}

export function buildTraditionsChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildTraditionsLesson(number, {}, reference));
}
